const items = $input.all();

function limpiar(valor) {
  return String(valor ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

function valorUtil(valor) {
  const v = limpiar(valor);

  if (!v) return '';

  const normalizado = v
    .toUpperCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

  if (
    normalizado === 'NO IDENTIFICADO' ||
    normalizado === 'NO ENCONTRADO' ||
    normalizado === 'NULL' ||
    normalizado === 'UNDEFINED'
  ) {
    return '';
  }

  return v;
}

return items.map(item => {
  const j = item.json || {};

  const empresa =
    valorUtil(j.empresa) ||
    valorUtil(j.empresa_mencionada) ||
    valorUtil(j.marca) ||
    valorUtil(j.organizacion) ||
    'NO IDENTIFICADO';

  const pais =
    valorUtil(j.pais) ||
    valorUtil(j.pais_objetivo) ||
    valorUtil(j.country);

  const ciudad =
    valorUtil(j.ciudad) ||
    valorUtil(j.ciudad_objetivo) ||
    valorUtil(j.city);

  return {
    json: {
      ...j,

      empresa_mencionada: empresa,

      pais_entrada:
        pais || 'NO IDENTIFICADO',

      ciudad_entrada:
        ciudad || 'NO IDENTIFICADO',

      pais_consulta: pais,

      ciudad_consulta: ciudad,

      contexto_regional_version:
        'RHIA_REGIONAL_V1',

      estado_contexto_regional:
        'PENDIENTE_RESOLUCION'
    }
  };
});

const items = $input.all();

function texto(valor) {
  return String(valor ?? '').trim();
}

function objeto(valor) {
  if (
    valor &&
    typeof valor === 'object' &&
    !Array.isArray(valor)
  ) {
    return valor;
  }

  try {
    return JSON.parse(valor || '{}');
  } catch {
    return {};
  }
}

function arreglo(valor) {
  if (Array.isArray(valor)) {
    return valor;
  }

  try {
    const parsed = JSON.parse(valor || '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

return items.map(item => {

  const j = item.json || {};

  const original =
    objeto(j.contexto_original);

  const mercado =
    objeto(j.mercado_pais);

  const candidatos =
    arreglo(j.candidatos_geograficos);

  const paisEntrada =
    texto(j.pais_entrada);

  const ciudadEntrada =
    texto(j.ciudad_entrada);

  const tienePais =
    paisEntrada !== '';

  const tieneCiudad =
    ciudadEntrada !== '';

  const primero =
    candidatos[0] || null;

  const segundo =
    candidatos[1] || null;


  let estado =
    'NO_RESUELTO';

  let confianza = 0;

  let paisResuelto =
    'NO IDENTIFICADO';

  let iso2 =
    'NO IDENTIFICADO';

  let ciudadResuelta =
    tieneCiudad
      ? ciudadEntrada
      : 'NO IDENTIFICADO';

  let provinciaEstado =
    'NO IDENTIFICADO';

  let ciudadId = null;
  let geonameId = null;

  let timezone =
    'NO IDENTIFICADO';

  let priorityTier = null;
  let priorityWeight = null;

  let callingCodes = [];
  let ccTlds = [];
  let currencyCodes = [];
  let languageCodes = [];

  let commercialScope =
    'NO IDENTIFICADO';

  let marketType =
    'NO IDENTIFICADO';


  // ==========================================================
  // CASO 1
  // PAÍS + CIUDAD PROPORCIONADOS Y RESUELTOS
  // ==========================================================

  if (
    tienePais &&
    tieneCiudad &&
    primero
  ) {

    estado =
      'RESUELTO';

    if (
      primero.city_match_type === 'EXACT_CITY_NAME' ||
      primero.city_match_type === 'EXACT_ASCII_NAME' ||
      primero.city_match_type === 'EXACT_ALIAS'
    ) {
      confianza = 100;
    } else {
      confianza = 90;
    }

    paisResuelto =
      mercado.country_name ||
      primero.country_name ||
      'NO IDENTIFICADO';

    iso2 =
      mercado.iso2 ||
      primero.market_iso2 ||
      'NO IDENTIFICADO';

    ciudadResuelta =
      primero.city_name ||
      ciudadEntrada;

    provinciaEstado =
      primero.admin1_name ||
      'NO IDENTIFICADO';

    ciudadId =
      primero.city_id || null;

    geonameId =
      primero.geoname_id || null;

    timezone =
      primero.timezone ||
      'NO IDENTIFICADO';

    priorityTier =
      mercado.priority_tier ??
      primero.priority_tier ??
      null;

    priorityWeight =
      mercado.priority_weight ??
      primero.priority_weight ??
      null;

    callingCodes =
      mercado.calling_codes || [];

    ccTlds =
      mercado.cc_tlds || [];

    currencyCodes =
      mercado.currency_codes || [];

    languageCodes =
      mercado.language_codes || [];

    commercialScope =
      mercado.commercial_scope ||
      'NO IDENTIFICADO';

    marketType =
      mercado.market_type ||
      'NO IDENTIFICADO';
  }


  // ==========================================================
  // CASO 2
  // PAÍS CONOCIDO SIN CIUDAD
  // ==========================================================

  else if (
    tienePais &&
    !tieneCiudad &&
    mercado.country_name
  ) {

    estado =
      'PAIS_RESUELTO_CIUDAD_NO_IDENTIFICADA';

    confianza = 95;

    paisResuelto =
      mercado.country_name;

    iso2 =
      mercado.iso2 ||
      'NO IDENTIFICADO';

    priorityTier =
      mercado.priority_tier ?? null;

    priorityWeight =
      mercado.priority_weight ?? null;

    callingCodes =
      mercado.calling_codes || [];

    ccTlds =
      mercado.cc_tlds || [];

    currencyCodes =
      mercado.currency_codes || [];

    languageCodes =
      mercado.language_codes || [];

    commercialScope =
      mercado.commercial_scope ||
      'NO IDENTIFICADO';

    marketType =
      mercado.market_type ||
      'NO IDENTIFICADO';
  }


  // ==========================================================
  // CASO 3
  // CIUDAD CONOCIDA SIN PAÍS
  // ==========================================================

  else if (
    !tienePais &&
    tieneCiudad &&
    primero
  ) {

    const scorePrimero =
      Number(primero.location_score || 0);

    const scoreSegundo =
      segundo
        ? Number(segundo.location_score || 0)
        : null;

    const diferencia =
      segundo
        ? scorePrimero - scoreSegundo
        : 999;

    const segundoFuerte =
      segundo &&
      scoreSegundo >= 95;

    const diferenteMercado =
      segundo &&
      segundo.market_iso2 !==
        primero.market_iso2;


    if (
      segundoFuerte &&
      diferenteMercado &&
      diferencia <= 5
    ) {

      // Hay dos ubicaciones plausibles en países distintos.
      // No heredamos NINGÚN atributo del primer candidato.

      estado =
        'AMBIGUO';

      confianza = 60;

      paisResuelto =
        'NO IDENTIFICADO';

      iso2 =
        'NO IDENTIFICADO';

      ciudadResuelta =
        ciudadEntrada;

      provinciaEstado =
        'NO IDENTIFICADO';

      ciudadId = null;
      geonameId = null;

      timezone =
        'NO IDENTIFICADO';

      priorityTier = null;
      priorityWeight = null;

      callingCodes = [];
      ccTlds = [];
      currencyCodes = [];
      languageCodes = [];

      commercialScope =
        'NO IDENTIFICADO';

      marketType =
        'NO IDENTIFICADO';

    } else {

      estado =
        'RESUELTO_POR_CIUDAD';

      confianza =
        segundo ? 85 : 95;

      paisResuelto =
        primero.country_name ||
        'NO IDENTIFICADO';

      iso2 =
        primero.market_iso2 ||
        'NO IDENTIFICADO';

      ciudadResuelta =
        primero.city_name ||
        ciudadEntrada;

      provinciaEstado =
        primero.admin1_name ||
        'NO IDENTIFICADO';

      ciudadId =
        primero.city_id || null;

      geonameId =
        primero.geoname_id || null;

      timezone =
        primero.timezone ||
        'NO IDENTIFICADO';

      priorityTier =
        primero.priority_tier ?? null;

      priorityWeight =
        primero.priority_weight ?? null;
    }
  }


  // ==========================================================
  // CASO 4
  // PAÍS PROPORCIONADO PERO NO RECONOCIDO
  // ==========================================================

  else if (
    tienePais &&
    !mercado.country_name &&
    !primero
  ) {

    estado =
      'PAIS_NO_RESUELTO';

    confianza = 0;

    ciudadResuelta =
      tieneCiudad
        ? ciudadEntrada
        : 'NO IDENTIFICADO';
  }


  // ==========================================================
  // CASO 5
  // SIN INFORMACIÓN GEOGRÁFICA
  // ==========================================================

  else {

    estado =
      'SIN_CONTEXTO_GEOGRAFICO';

    confianza = 0;
  }


  return {
    json: {

      ...original,

      empresa_mencionada:
        j.empresa_mencionada ||
        original.empresa_mencionada ||
        original.empresa ||
        'NO IDENTIFICADO',

      pais_entrada:
        paisEntrada ||
        'NO IDENTIFICADO',

      ciudad_entrada:
        ciudadEntrada ||
        'NO IDENTIFICADO',

      pais_resuelto:
        paisResuelto,

      market_iso2:
        iso2,

      ciudad_resuelta:
        ciudadResuelta,

      provincia_estado:
        provinciaEstado,

      city_id:
        ciudadId,

      geoname_id:
        geonameId,

      timezone,

      priority_tier:
        priorityTier,

      priority_weight:
        priorityWeight,

      calling_codes:
        callingCodes,

      cc_tlds:
        ccTlds,

      currency_codes:
        currencyCodes,

      language_codes:
        languageCodes,

      commercial_scope:
        commercialScope,

      market_type:
        marketType,

      estado_geografico:
        estado,

      confianza_geografica:
        confianza,

      requiere_resolucion_adicional:
        [
          'AMBIGUO',
          'PAIS_NO_RESUELTO',
          'SIN_CONTEXTO_GEOGRAFICO'
        ].includes(estado),

      candidatos_geograficos:
        candidatos,

      contexto_regional_version:
        'RHIA_REGIONAL_V1'
    }
  };
});

const items = $input.all();

function limpiar(valor) {
  return String(valor ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizar(valor) {
  return limpiar(valor)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function esIdentificado(valor) {
  const v = normalizar(valor);

  return (
    v !== '' &&
    v !== 'no identificado' &&
    v !== 'no encontrado' &&
    v !== 'null' &&
    v !== 'undefined'
  );
}

function textoBusqueda(valor) {
  const v = limpiar(valor);

  if (!esIdentificado(v)) {
    return '';
  }

  return `"${v}"`;
}

return items.map(item => {

  const j = item.json || {};

  // =========================================================
  // 1. MARCA / EMPRESA MENCIONADA
  // =========================================================

  const empresa =
    limpiar(
      j.empresa_mencionada ||
      j.empresa ||
      j.marca ||
      j.organizacion
    ) || 'NO IDENTIFICADO';

  const empresaKey =
    normalizar(empresa);


  // =========================================================
  // 2. CONTEXTO GEOGRÁFICO
  // =========================================================

  const estadoGeografico =
    limpiar(j.estado_geografico) ||
    'SIN_CONTEXTO_GEOGRAFICO';

  const paisResuelto =
    esIdentificado(j.pais_resuelto)
      ? limpiar(j.pais_resuelto)
      : '';

  const iso2Resuelto =
    esIdentificado(j.market_iso2)
      ? limpiar(j.market_iso2)
      : '';

  const ciudadResuelta =
    esIdentificado(j.ciudad_resuelta)
      ? limpiar(j.ciudad_resuelta)
      : '';

  const provinciaEstado =
    esIdentificado(j.provincia_estado)
      ? limpiar(j.provincia_estado)
      : '';

  const candidatosGeo =
    Array.isArray(j.candidatos_geograficos)
      ? j.candidatos_geograficos
      : [];


  // =========================================================
  // 3. CONSTRUIR CONTEXTOS DE BÚSQUEDA
  //
  // Si el país ya está resuelto:
  //   usamos únicamente ese mercado.
  //
  // Si está ambiguo:
  //   conservamos hasta 3 países candidatos diferentes.
  //
  // Nunca elegimos uno arbitrariamente.
  // =========================================================

  const contextos = [];


  if (paisResuelto && iso2Resuelto) {

    contextos.push({
      market_iso2: iso2Resuelto,
      pais: paisResuelto,
      ciudad: ciudadResuelta,
      provincia_estado: provinciaEstado,
      origen: 'UBICACION_RESUELTA',
      confianza_geografica:
        Number(j.confianza_geografica || 0)
    });

  } else if (
    estadoGeografico === 'AMBIGUO' &&
    candidatosGeo.length > 0
  ) {

    const mercadosVistos = new Set();

    for (const candidato of candidatosGeo) {

      const iso2 =
        limpiar(candidato.market_iso2);

      const pais =
        limpiar(candidato.country_name);

      if (!iso2 || !pais) {
        continue;
      }

      if (mercadosVistos.has(iso2)) {
        continue;
      }

      mercadosVistos.add(iso2);

      contextos.push({
        market_iso2: iso2,
        pais: pais,
        ciudad:
          limpiar(candidato.city_name),
        provincia_estado:
          limpiar(candidato.admin1_name),
        origen:
          'CANDIDATO_GEOGRAFICO',
        location_score:
          Number(candidato.location_score || 0)
      });

      if (contextos.length >= 3) {
        break;
      }
    }

  }


  // Si no pudimos obtener ningún mercado,
  // generamos un contexto regional sin asumir país.

  if (contextos.length === 0) {

    contextos.push({
      market_iso2: '',
      pais: '',
      ciudad:
        ciudadResuelta ||
        limpiar(j.ciudad_entrada),
      provincia_estado: '',
      origen:
        'SIN_MERCADO_RESUELTO'
    });
  }


  // =========================================================
  // 4. GENERAR CONSULTAS DE RESOLUCIÓN DE ENTIDAD
  // =========================================================

  const consultas = [];

  for (const contexto of contextos) {

    const empresaQ =
      textoBusqueda(empresa);

    const paisQ =
      textoBusqueda(contexto.pais);

    const ciudadQ =
      textoBusqueda(contexto.ciudad);

    const geografia =
      [paisQ, ciudadQ]
        .filter(Boolean)
        .join(' ');


    // ---------------------------------------------------------
    // SITIO / PRESENCIA OFICIAL
    // ---------------------------------------------------------

    consultas.push({
      tipo: 'SITIO_OFICIAL',
      market_iso2:
        contexto.market_iso2,
      pais:
        contexto.pais ||
        'NO IDENTIFICADO',
      ciudad:
        contexto.ciudad ||
        'NO IDENTIFICADO',
      contexto_origen:
        contexto.origen,

      q:
        `${empresaQ} ${geografia} ` +
        `("sitio oficial" OR official OR corporativo)`
    });


    // ---------------------------------------------------------
    // OPERADOR LOCAL / FRANQUICIADO / LICENCIATARIO
    // ---------------------------------------------------------

    consultas.push({
      tipo: 'OPERADOR_LOCAL',
      market_iso2:
        contexto.market_iso2,
      pais:
        contexto.pais ||
        'NO IDENTIFICADO',
      ciudad:
        contexto.ciudad ||
        'NO IDENTIFICADO',
      contexto_origen:
        contexto.origen,

      q:
        `${empresaQ} ${geografia} ` +
        `(operador OR "operador local" OR franquicia ` +
        `OR franquiciado OR franchisee OR licensee ` +
        `OR licenciatario OR representación ` +
        `OR representante OR distribuidor)`
    });


    // ---------------------------------------------------------
    // ENTIDAD LEGAL / RAZÓN SOCIAL
    // ---------------------------------------------------------

    consultas.push({
      tipo: 'ENTIDAD_LEGAL',
      market_iso2:
        contexto.market_iso2,
      pais:
        contexto.pais ||
        'NO IDENTIFICADO',
      ciudad:
        contexto.ciudad ||
        'NO IDENTIFICADO',
      contexto_origen:
        contexto.origen,

      q:
        `${empresaQ} ${paisQ} ` +
        `("razón social" OR "razon social" ` +
        `OR "legal entity" OR sociedad OR compañía ` +
        `OR compania OR S.A. OR S.A.S. OR SAS)`
    });


    // ---------------------------------------------------------
    // ENTIDAD EMPLEADORA
    // ---------------------------------------------------------

    consultas.push({
      tipo: 'ENTIDAD_EMPLEADORA',
      market_iso2:
        contexto.market_iso2,
      pais:
        contexto.pais ||
        'NO IDENTIFICADO',
      ciudad:
        contexto.ciudad ||
        'NO IDENTIFICADO',
      contexto_origen:
        contexto.origen,

      q:
        `${empresaQ} ${geografia} ` +
        `("trabaja con nosotros" OR empleos OR empleo ` +
        `OR careers OR jobs OR "talento humano" ` +
        `OR "recursos humanos" OR contratación ` +
        `OR contratacion OR selección OR seleccion)`
    });


    // ---------------------------------------------------------
    // GRUPO EMPRESARIAL / HOLDING / PROPIETARIO
    // ---------------------------------------------------------

    consultas.push({
      tipo: 'GRUPO_EMPRESARIAL',
      market_iso2:
        contexto.market_iso2,
      pais:
        contexto.pais ||
        'NO IDENTIFICADO',
      ciudad:
        contexto.ciudad ||
        'NO IDENTIFICADO',
      contexto_origen:
        contexto.origen,

      q:
        `${empresaQ} ${paisQ} ` +
        `("grupo empresarial" OR holding OR grupo ` +
        `OR propietario OR owner OR parent company ` +
        `OR subsidiaria OR subsidiary)`
    });


    // ---------------------------------------------------------
    // PRESENCIA LOCAL
    //
    // Útil para marcas que tienen operadores diferentes
    // por país o ciudad.
    // ---------------------------------------------------------

    if (contexto.ciudad) {

      consultas.push({
        tipo: 'PRESENCIA_LOCAL',
        market_iso2:
          contexto.market_iso2,
        pais:
          contexto.pais ||
          'NO IDENTIFICADO',
        ciudad:
          contexto.ciudad,
        contexto_origen:
          contexto.origen,

        q:
          `${empresaQ} ${ciudadQ} ${paisQ}`
      });
    }
  }


  // =========================================================
  // 5. SALIDA
  // =========================================================

  return {
    json: {

      ...j,

      marca_mencionada:
        empresa,

      empresa_mencionada:
        empresa,

      empresa_key:
        empresaKey,

      estado_resolucion_entidad:
        'PENDIENTE',

      entidad_operadora:
        'NO IDENTIFICADO',

      entidad_empleadora:
        'NO IDENTIFICADO',

      grupo_empresarial:
        'NO IDENTIFICADO',

      tipo_relacion:
        'NO IDENTIFICADO',

      confianza_resolucion_entidad:
        0,

      contextos_busqueda_entidad:
        contextos,

      consultas_resolucion_entidad:
        consultas,

      cantidad_contextos_entidad:
        contextos.length,

      cantidad_consultas_entidad:
        consultas.length,

      requiere_evidencia_entidad:
        true,

      reglas_resolucion_entidad: {

        no_asumir_marca_como_empresa:
          true,

        no_asumir_operador_como_empleador:
          true,

        no_asumir_pais_ambiguo:
          true,

        exigir_evidencia_relacion:
          true,

        preservar_fuentes:
          true,

        permitir_franquicia:
          true,

        permitir_licencia:
          true,

        permitir_distribuidor:
          true,

        permitir_subsidiaria:
          true,

        permitir_grupo_empresarial:
          true
      },

      siguiente_accion_entidad:
        'BUSCAR_EVIDENCIA_ENTIDAD'
    }
  };
});

const respuestas = $input.all();

const originales =
  $('Separar consultas entidad').all();

if (
  respuestas.length !==
  originales.length
) {
  throw new Error(
    `DESALINEACION_ITEMS: Buscar evidencia entregó ${respuestas.length} items, pero Separar consultas entidad tiene ${originales.length}.`
  );
}

return respuestas.map(
  (item, index) => {

    const original =
      originales[index]?.json || {};

    const consulta =
      original.consultas_resolucion_entidad || {};

    const respuesta =
      item.json || {};

    const resultados =
      Array.isArray(respuesta.results)
        ? respuesta.results
        : [];

    return {

      json: {

        empresa_mencionada:
          original.empresa_mencionada ||
          original.empresa ||
          'NO IDENTIFICADO',

        empresa_key:
          original.empresa_key ||
          'NO IDENTIFICADO',

        tipo_consulta:
          consulta.tipo ||
          'NO IDENTIFICADO',

        market_iso2_consulta:
          consulta.market_iso2 ||
          'NO IDENTIFICADO',

        pais_consulta_entidad:
          consulta.pais ||
          'NO IDENTIFICADO',

        ciudad_consulta_entidad:
          consulta.ciudad ||
          'NO IDENTIFICADO',

        contexto_origen:
          consulta.contexto_origen ||
          'NO IDENTIFICADO',

        query_original:
          consulta.q ||
          respuesta.query ||
          'NO IDENTIFICADO',

        total_resultados:
          resultados.length,

        resultados_searxng:
          resultados,

        answers:
          Array.isArray(respuesta.answers)
            ? respuesta.answers
            : [],

        corrections:
          Array.isArray(respuesta.corrections)
            ? respuesta.corrections
            : [],

        infoboxes:
          Array.isArray(respuesta.infoboxes)
            ? respuesta.infoboxes
            : [],

        suggestions:
          Array.isArray(respuesta.suggestions)
            ? respuesta.suggestions
            : [],

        unresponsive_engines:
          Array.isArray(
            respuesta.unresponsive_engines
          )
            ? respuesta.unresponsive_engines
            : [],

        estado_busqueda_evidencia:
          resultados.length > 0
            ? 'RESULTADOS_ENCONTRADOS'
            : 'SIN_RESULTADOS',

        contexto_geografico_original: {

          pais_resuelto:
            original.pais_resuelto ||
            'NO IDENTIFICADO',

          market_iso2:
            original.market_iso2 ||
            'NO IDENTIFICADO',

          ciudad_resuelta:
            original.ciudad_resuelta ||
            'NO IDENTIFICADO',

          estado_geografico:
            original.estado_geografico ||
            'NO IDENTIFICADO',

          confianza_geografica:
            original.confianza_geografica ??
            null
        }
      },

      pairedItem: {
        item: index
      }
    };
  }
);

const items = $input.all();

function limpiar(v) {
  return String(v ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

function norm(v) {
  return limpiar(v)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[’‘`´']/g, '')
    .replace(/[^a-z0-9áéíóúüñ\s.-]/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function dominio(url) {
  const texto = limpiar(url);

  if (!texto) {
    return '';
  }

  const match = texto.match(
    /^(?:https?:\/\/)?(?:www\.)?([^\/?#:]+)/i
  );

  return match
    ? String(match[1]).toLowerCase()
    : '';
}

function contiene(texto, palabras) {
  const t = norm(texto);

  return palabras.some(
    p => t.includes(norm(p))
  );
}

function empresaPresente(texto, empresa) {
  const t = norm(texto);
  const e = norm(empresa);

  if (!e) {
    return false;
  }

  return t.includes(e);
}

function fuenteTipo(domain) {

  if (!domain) {
    return 'DESCONOCIDA';
  }

  if (
    domain.endsWith('.gov') ||
    domain.endsWith('.gob') ||
    domain.includes('.gov.') ||
    domain.includes('.gob.')
  ) {
    return 'GOBIERNO';
  }

  if (
    domain.includes('linkedin.com')
  ) {
    return 'LINKEDIN';
  }

  if (
    domain.includes('facebook.com') ||
    domain.includes('instagram.com') ||
    domain.includes('tiktok.com') ||
    domain === 'x.com' ||
    domain.endsWith('.x.com')
  ) {
    return 'RED_SOCIAL';
  }

  if (
    domain.includes('researchgate.net') ||
    domain.includes('academia.edu') ||
    domain.includes('studocu.com') ||
    domain.includes('coursehero.com') ||
    domain.includes('scribd.com')
  ) {
    return 'ACADEMICA_SECUNDARIA';
  }

  if (
    domain.includes('scielo.') ||
    domain.includes('.edu') ||
    domain.includes('.ac.')
  ) {
    return 'ACADEMICA';
  }

  return 'WEB';
}

function pesoFuente(tipo) {
